#!/bin/sh
# Generate the protocol sources from the one schema into the tracked tree,
# so the server builds on a machine with no flatc.
#
#   ./generate.sh [outdir]        default: ../src/protocol
#
# Output is a generated tree and is replaced wholesale, so a table removed
# from the schema does not leave its file behind.
#
# **Run this with the flatc that matches the libflatbuffers of the machine
# meant to build without one.** flatc writes its own version into the C++ as
# a static_assert, so a header generated by flatc 25 does not compile against
# the flatbuffers 23 headers. Where flatc *is* installed the build generates
# afresh and ignores this tree entirely, so the constraint only binds the
# machines that have none.
set -e
cd "$(dirname "$0")"
out="${1:-../src/protocol}"
mkdir -p "$out"
out="$(cd "$out" && pwd)"

rm -rf "$out/cpp" "$out/ts" "$out/lcfb.bfbs"
flatc --ts  --gen-all -o "$out/ts"  lcfb.fbs
flatc --cpp --gen-all --scoped-enums --gen-compare -o "$out/cpp" lcfb.fbs
# The reflection schema, so either side can render a frame as JSON without
# the .fbs sources. Same schema, same run: it cannot drift from the code.
flatc -b --schema --bfbs-builtins -o "$out" lcfb.fbs
cp ids.ts "$out/ts/"
cp ids.h  "$out/cpp/"
echo "generated into $out with $(flatc --version)"
